% zero-length path
\draw[line width=2pt] (0,0) -- (0,0);
\node[font=\tiny, below] at (0,-0.2) {zero-length};
% degenerate circle / rectangle
\draw (2,0) circle (0pt);
\draw (3.5,-0.3) rectangle (3.5,-0.3);
\node[font=\tiny, below] at (2.75,-0.5) {r=0, empty rect};
% single-point plot
\draw[Stealth-Stealth] plot coordinates {(5,0)};
\node[font=\tiny, below] at (5,-0.3) {1-point plot};
% duplicate node name: second definition of (dup)
\node[draw, fill=blue!15] (dup) at (0,2) {first dup};
\node[draw, fill=red!15]  (dup) at (2.2,2) {second dup};
\draw[-Stealth, thick] (dup) -- (4.5,2);
\node[font=\tiny, right] at (4.5,2) {arrow went to WHICH dup?};
% self-referencing edge
\node[draw, circle] (self) at (0,4) {S};
\draw[-Stealth] (self) to[loop above] (self);
\draw[-Stealth] (self) to[out=0,in=180] (self);
% exactly colliding coordinates
\node[draw, fill=green!20] at (4,4) {collide A};
\node[draw, fill=yellow!30] at (4,4) {collide B};
\node[font=\tiny, below=0.9cm] at (4,4) {two nodes, identical coords};
